 public static void VerifyModel(){
  var legacy=JsonUtility.FromJson<SliceState>("{}");Check(legacy.Valid()&&legacy.StormChapter.recovery==null,"Legacy season invented recovery");var before=JsonUtility.ToJson(legacy);StormRecoveryText.Read(legacy,4,5,null);Check(before==JsonUtility.ToJson(legacy),"Recovery Book mutated legacy state");
  var chapter=new StormChapterState{phase=StormPhase.Recovery,resolved=true,opportunity=true,villager=0,source=RescueSource.Creature,recovery=new StormRecoveryState{recorded=true,thanked=true,until=180}};Check(chapter.Valid()&&JsonUtility.FromJson<StormChapterState>(JsonUtility.ToJson(chapter)).Valid(),"Recovery did not round trip");chapter.source=RescueSource.Player;Check(!chapter.Valid(),"Player rescue accepted creature thanks");chapter.recovery.thanked=false;Check(chapter.Valid(),"Player recovery rejected");chapter.recovery.until=float.NaN;Check(!chapter.Valid(),"Nonfinite recovery timer accepted");var m=new SocialMemory{stormsSurvived=1,stormCreatureRescues=1,stormThanks=2};Check(!m.Valid(),"Duplicate thanks memory accepted");
