 public static void VerifyRuntime(){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var chapter=slice.Chapter;var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>().world;Check(!nav.TreeNavigationPending,"Wait for navigation");var weather=slice.GetComponentInChildren<IslandWeather>();var ball=slice.GetComponentInChildren<BeachBall>();var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);bool automatic=weather.automatic;var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var held=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(held.All(i=>i==null),"Release held items");SliceState test=null;
  void Stage(){chapter.Stop();god.Interrupt("Recovery QA");foreach(var p in people){p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(p.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(p.GetComponent<VillagerRoutine>());p.GetComponent<CarryItem>().held=false;}
   test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f};field.SetValue(slice,test);chapter.Advance(.01f,false);god.NewSeason();ball.ResetWorld();weather.ResetWorld();slice.SetSanctuaryOpen(false);foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var p in people){p.Memory.injury=0;p.Memory.lastFrightAt=-100;p.Memory.trust=.6f;p.transform.position=gp+Vector3.up*nav.Scale*600;}Check(nav.Sample(ball.Bowling.Start,nav.creature,4,out var start),"No creature start");god.transform.position=nav.ProjectFoot(start,nav.creature);var person=people[0];bool visible=false;for(int k=0;k<24&&!visible;k++){var wanted=god.transform.position+Quaternion.Euler(0,k*15,0)*ball.Bowling.Right*nav.Scale*12;if(!person.GetComponent<IslandNavigator>().CanPlace(wanted,out var at))continue;person.transform.position=at;god.transform.LookAt(new Vector3(at.x,god.transform.position.y,at.z));Physics.SyncTransforms();visible=god.CanSeeCue(person.GetComponent<HybridTarget>(),false,true);}Check(visible,"No visible survivor stage");god.GetComponent<IslandNavigator>().ResetRoute();foreach(var pair in cooldowns)pair.Key.cooldown=100000;person.GetComponent<CreatureAffordance>().cooldown=0;Check(chapter.Start(),"Start rejected");chapter.State.phase=StormPhase.Storm;chapter.State.elapsed=0;weather.State.Set(IslandWeatherKind.Rain,150);chapter.Advance(.05f,false);Check(chapter.Pending&&chapter.Person==person,"No staged survivor opportunity");
  }
  void Tick(float dt,bool ai=false){if(test.paused){chapter.Advance(dt,true);return;}test.Hybrid.time+=dt;chapter.Advance(dt,false);foreach(var p in people){var actor=p.GetComponent<VillagerExploration>();if(!chapter.TickVillager(p.GetComponent<VillagerRoutine>(),dt)&&actor.Active)actor.Tick(dt,false);}if(ai)god.Tick(dt,false);}
  void Recover(){god.Interrupt("Recovery stage after confirmed rescue");foreach(var p in people)p.GetComponent<VillagerExploration>().ResetTask();chapter.State.elapsed=StormChapterState.Duration(StormPhase.Storm)-.01f;Tick(.05f);weather.State.rain=0;Check(chapter.State.phase==StormPhase.Recovery&&chapter.Recovery.recorded&&people[0].Memory.stormsSurvived==1,"Recovery not recorded once");}
  void PlayerArrival(){var item=people[0].GetComponent<CarryItem>();Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,item}),"Native pickup failed");typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,new Ray(chapter.Refuge+Vector3.up*nav.Scale*30,Vector3.down)});Check(chapter.State.source==RescueSource.Player,"Native player rescue not credited");}
  void NearCreature(){var person=people[0];var side=person.transform.position-god.transform.position;side.y=0;if(side.sqrMagnitude<1e-10f)side=Vector3.right;Check(person.GetComponent<IslandNavigator>().CanPlace(god.transform.position+side.normalized*nav.Scale*7,out var at),"No acknowledgment stage");person.transform.position=at;person.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();}
  try{
   Stage();Check(god.Guide(GuidanceIntent.Help,people[0].GetComponent<HybridTarget>()),"Help cue rejected");for(int i=0;i<2400&&!chapter.State.resolved;i++)Tick(.05f,true);Check(chapter.State.source==RescueSource.Creature,"Creature did not physically rescue survivor");Recover();NearCreature();var actor=people[0].GetComponent<VillagerExploration>();test.Hybrid.time+=6;Check(chapter.TickVillager(people[0].GetComponent<VillagerRoutine>(),.05f)&&actor.StormThanking,"No autonomous gratitude approach");var before=JsonUtility.ToJson(test);test.paused=true;var paused=JsonUtility.ToJson(test);for(int i=0;i<20;i++){Tick(.05f);actor.Tick(.05f,true);}Check(paused==JsonUtility.ToJson(test),"Pause advanced gratitude");test.paused=false;typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);var pendingJson=System.IO.File.ReadAllText(System.IO.Path.Combine(Application.persistentDataPath,"bwvr-season-v1.json"));typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();chapter.Advance(.01f,false);Check(!actor.StormThanking&&chapter.Recovery.recorded&&!chapter.Recovery.thanked&&people[0].Memory.stormsSurvived==1,"Pending native resume retained gesture ownership or replayed survival");NearCreature();test.Hybrid.time+=6;for(int i=0;i<500&&!chapter.Recovery.thanked;i++)Tick(.05f);Check(chapter.Recovery.thanked&&people[0].Memory.stormThanks==1&&people[0].Memory.stormCreatureRescues==1&&!chapter.ConfirmStormThanks(actor),"Thanks missing or duplicated");Check(test.Hybrid.receipt.action!=CreatureAction.PlayWithToy,"Gratitude invented toy completion");
   actor.ResetTask();Check(nav.Sample(ball.Bowling.Start,nav.villager,4,out var stage),"No ball stage");people[0].transform.position=nav.ProjectFoot(stage,nav.villager);ball.PlaceOnGround(stage+ball.Bowling.Right*nav.Scale*10);Check(nav.Sample(stage-ball.Bowling.Right*nav.Scale*12,nav.creature,5,out var foot),"No return god stage");god.transform.position=nav.ProjectFoot(foot,nav.creature);god.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();Check(actor.TryStormReturnPlay(chapter),"Return-to-play approach unavailable");Check(!chapter.Recovery.invited&&!chapter.ConfirmStormInvitation(actor,ball),"Approach fabricated invitation receipt");for(int i=0;i<1200&&!chapter.Recovery.invited;i++)Tick(.05f);Check(chapter.Recovery.invited&&chapter.Recovery.closed&&people[0].Memory.stormPlayInvitations==1&&people[0].Memory.ballInvitations==1&&ball.OwnsPlayer(actor),"Physical invitation did not complete through normal ball controller");Check(!chapter.ConfirmStormInvitation(actor,ball)&&people[0].Memory.stormPlayInvitations==1,"Repeated invitation credited twice");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();chapter.Advance(.01f,false);Check(test.Valid()&&chapter.Recovery.thanked&&chapter.Recovery.invited&&people[0].Memory.stormThanks==1&&people[0].Memory.stormPlayInvitations==1&&!actor.StormThanking&&!ball.OwnsPlayer(actor),"Completed native resume replayed gratitude/play ownership");
   System.IO.File.WriteAllText(System.IO.Path.Combine(Application.persistentDataPath,"bwvr-season-v1.json"),pendingJson);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();chapter.Advance(.01f,false);NearCreature();actor.ResetTask();Check(actor.TryStormThanks(chapter),"Interrupt fixture could not acknowledge");people[0].GetComponent<CarryItem>().held=true;Check(!chapter.ConfirmStormThanks(actor),"Held actor awarded thanks");actor.Tick(.05f,false);people[0].GetComponent<CarryItem>().held=false;Check(!actor.StormThanking&&!chapter.Recovery.thanked&&people[0].Memory.stormThanks==0,"Pickup awarded gratitude");Check(actor.TryStormThanks(chapter),"Stop fixture could not acknowledge");test.paused=true;Check(chapter.Stop()&&chapter.Recovery.closed&&!actor.StormThanking&&!chapter.Recovery.thanked,"Paused stop retained acknowledgment owner");test.paused=false;
   Stage();PlayerArrival();Recover();Check(!chapter.NeedsStormThanks&&people[0].Memory.stormCreatureRescues==0&&people[0].Memory.stormThanks==0&&!people[0].GetComponent<VillagerExploration>().TryStormThanks(chapter),"Player intervention received creature gratitude");test.Hybrid.time=chapter.Recovery.until+1;chapter.Advance(.05f,false);Check(chapter.Recovery.closed&&!chapter.Recovery.invited,"Expiry invented invitation");
   Stage();for(int i=0;i<2400&&!chapter.State.resolved;i++)Tick(.05f);Check(chapter.State.source==RescueSource.Independent,"Independent evacuation unavailable");Recover();Check(!chapter.NeedsStormThanks&&people[0].Memory.stormCreatureRescues==0&&!test.Hybrid.receipt.eligible,"Independent arrival credited creature");
   var legacy=new SliceState{stormChapter=new StormChapterState{phase=StormPhase.Complete,episode=1,opportunity=true,resolved=true,villager=0,source=RescueSource.Creature}};field.SetValue(slice,legacy);god.NewSeason();chapter.Advance(.05f,false);Check(chapter.Recovery==null&&legacy.Social(0).stormsSurvived==0,"Historical completed storm retroactively granted memory");
   Debug.Log("BWVR_STORM_RECOVERY_RUNTIME_PASS: actual utility-selected rescue, exactly-once remembered survival, native gratitude gesture and pause, physical ball invitation receipt, source isolation, expiry, historical saves and completed native Save/Load");
  }finally{held[0]=held[1]=null;god.Interrupt("Recovery QA finished");chapter.Stop();foreach(var p in people){p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<CarryItem>().held=false;p.GetComponent<Collider>().enabled=true;}field.SetValue(slice,original);chapter.Advance(.01f,false);weather.automatic=automatic;god.NewSeason();ball.ResetWorld();weather.ResetWorld();foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
